struct VSOut
{
    float4 pos : SV_POSITION;
    float2 uv  : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    float2 uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(uv * 2.0 - 1.0, 0.0, 1.0);
    o.uv = uv;
    o.uv.y = 1.0 - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut
{
    float4 pos : SV_POSITION;
    float2 uv  : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float t = time_sim_ms * 0.001;

    float3 color = float3(0, 0, 0);
    for (int k = 0; k < 5; k++) {
        float phase = float(k) * 1.2566;
        float2 center = float2(0.5 + 0.3 * cos(t + phase), 0.5 + 0.3 * sin(t * 0.7 + phase));
        float dist = length(uv - center);
        float glow = 0.02 / (dist * dist + 0.01);
        float3 c;
        c.r = glow * (0.5 + 0.5 * sin(phase));
        c.g = glow * (0.5 + 0.5 * sin(phase + 2.094));
        c.b = glow * (0.5 + 0.5 * sin(phase + 4.189));
        color += c;
    }
    return float4(color * 0.15, 1.0);
}
